from corpus import *
from datetime import date
import html, hashlib, xml.etree.ElementTree as ET

def literal(data):
    if isinstance(data,list): return '\n'.join(data)
    return str(data)

def main():
    from french_sources import french_source_records
    french_sources=french_source_records()
    french_reviews={p.stem:read_json(p) for p in (REVIEWED).glob('*.json') if read_json(p).get('french_review')}
    french_ui_keys={x['key'] for p in (ROOT/'localization/contexts').glob('*_ui.json') for x in read_json(p).get('keys',[]) if isinstance(x,dict) and x.get('french_priority_reviewed')}
    french_ui={x['_key']:x['_value'] for x in read_json(ROOT/'original/LocalizationData/sharedassets0.assets/2097.json')['_items']}
    french_audit=read_json(ROOT/'localization/french_priority_audit.json')
    ui_batches=[read_json(p) for p in (ROOT/'localization/contexts').glob('000_*batch*_ui.json')]
    batch_keys=[item for batch in ui_batches for item in batch.get('keys',[]) if isinstance(item,dict) and item.get('french_priority_reviewed')]
    batch_changed=sum(item.get('previous_contextual_russian',item['russian'])!=item['russian'] for item in batch_keys)
    alias_path=ROOT/'review/ui_extra_alias_audit.json'
    legacy_aliases=read_json(alias_path)['records'] if alias_path.exists() else []
    current_table=read_json(UI_KEYS)
    for item in legacy_aliases:
        assert item['russian']==current_table[item['alias']]==current_table[item['original_key']],('Stale legacy alias report',item['alias'])
    legacy_changes=[x for x in legacy_aliases if x['baseline']!=x['russian']]
    story_report=read_json(ROOT/'localization/story_validation.json')
    changes=read_json(ROOT/'review/changes.json')
    from ui_changelog import current_ui_changes
    changes=current_ui_changes(changes,french_ui_keys)
    name_path=ROOT/'review/name_changes.json'
    if name_path.exists():changes+=read_json(name_path)
    full_path=ROOT/'review/full_review_changes.json'
    if full_path.exists():
        full=read_json(full_path)
        refs={(x['object'],x['passage']) for x in full}
        changes=[x for x in changes if x['category']!='dialogue' or (x['object'],x['passage']) not in refs]+full
    newspaper_work=ROOT/'review/newspaper_repairs_working.json'
    if newspaper_work.exists():
        work=read_json(newspaper_work);record=work['record']
        for field in ['modifier_renames','random_target_lists','exhaustion_fallbacks']:
            for fix in record[field]:
                before=fix.get('source',fix.get('source_lines'))
                after=fix['target'] if field!='exhaustion_fallbacks' else fix['source_lines']+['-> '+fix['target']]
                changes.append(dict(category='structure',phase='newspaper_source_defect_repair',object=work['scene'],passage=fix['passage'],
                    english=before,french=before,before=before,after=after,
                    reason='Адресное исправление исходного служебного дефекта газетной ветки после исполнения оригиналов. Все существующие реплики, ответы и команды сохранены; детали и границы — NEWSPAPER_REPAIRS_RU.md.'))
    valid=read_json(ROOT/'review/native_validation.json')
    stats=read_json(ROOT/'review/stats.json')
    ui=[x for x in changes if x['category']=='ui']
    dialogs=[x for x in changes if x['category']=='dialogue']
    characters=[x for x in changes if x['category']=='character']
    calls=[x for x in changes if x['category']=='passenger_call']
    structural=[x for x in changes if x['category']=='structure']
    speakers=collections.Counter((x['before'],x['after']) for x in read_json(ROOT/'review/native_text_changes.json'))
    lines=['# Журнал изменений русского перевода Night Call', '',
        *(['Титры: ограничена ширина контейнера Credits Roller в двух сценах (level3/1571 и level7/910). Длинная благодарность Josepha Guigues переносится внутри окна; весь текст сохранён. Это два изменения вёрстки, не новые переводы. Точная правка, живая проверка и ограничения — CREDITS_LAYOUT_RU.md.', ''] if (ROOT/'localization/credits_layout.json').exists() else []),
        *(['Газеты: 40 адресных технических правок — 29 имён переменных, два списка с отсутствующими статьями и девять выходов из исчерпанных списков улик. Все 174 русские строки и четыре ответа прежние. Нативное включение отслеживается отдельно. '+('Добавлены два отсутствовавших поля существующей улики Судьи09 по французской статье и исходному ресурсу; подробности — NEWSPAPER_CLUE_UI_RU.md.' if (ROOT/'localization/native_ui_extensions.json').exists() else 'Два отсутствующих поля карточки улики остаются отдельной задачей.')+' Подробности сценария — NEWSPAPER_REPAIRS_RU.md.', ''] if newspaper_work.exists() else []),
        *(['Каролина: ещё 28 текстовых правок после полной повторной FR-вычитки. Уточнены голос, иронические слухи, обустройство отеля, мужья постоялиц, мимика, масштаб малых добрых дел и отъезд такси. Подробнее — CAROLINA_FOLLOWUP_CHANGES_RU.md. '+('Эти строки включены в нативные ресурсы; текущая приёмка и границы — CAROLINA_INTEGRATION_RU.md.' if (ROOT/'localization/carolina_integration_validation.json').exists() else 'Эти новые строки ещё требуют отдельной нативной сборки; последний установочный ZIP относится к предыдущему вводу.'), ''] if (ROOT/'review/carolina_followup_working.json').exists() else []),
        f'Рабочая контекстная редакция от {date.today():%d.%m.%Y}. Полная русификация продолжается.', '',
        'Журнал отражает текущую редактуру исходников. Исторические результаты r1 ниже не подтверждают следующие этапы. Актуальный нативный WIP и его проверки — review/LATEST_NATIVE_FR_WIP.json; границы живой проверки — LIVE_QA_RU.md, если файл существует. Полный релиз ещё не принят.', '',
        'С15.10.2026 по указанию пользователя французский текст принят основным смысловым источником. Прежние записи редактуры сохраняются; решения с приоритетом английского подлежат повторной сверке. Охват этой новой проверки отдельно учтён в localization/french_priority_audit.json и не равен числу ранее отредактированных сцен.', '',
        f'Текущая французская сверка: {french_audit["reviewed"]}/{french_audit["total"]} диалоговых сцен и {french_audit["ui_reviewed"]}/{french_audit["ui_total"]} полей интерфейса. Не приняты ещё {len(french_audit["ui_pending"])} полей. Сверка текста не означает завершения нативной сборки и проверки в игре.', '',
        'Основа: русификатор Artem Lytkin (4RH1T3CT0R), репозиторий https://github.com/4RH1T3CT0R7/russian-localisation-night-call, коммит `c69ff4c34014bbfbd9f89ba9b8d45d03ac547b8d`.', '',
        f'В журнале {len(changes)} записей редактуры: {len(ui)} изменений интерфейса/досье, {len(characters)} имён персонажей, {len(dialogs)} блоков диалогов, {len(calls)} фраз заказа такси и {len(structural)} исправлений исходных переходов. Это количество записей, а не количество независимо подтверждённых смысловых ошибок: один блок может включать много правок.', '',
        f'Ещё {len(legacy_changes)} изменений унаследованных служебных и поисковых подписей старого мода показаны отдельной таблицей ниже; они не прибавляются к 921 исходному полю игры.', '',
          '## Существенные исправления', '',
        *(['- Повторно полностью перечитана сцена Леони: 34 языковых/контекстных правки (30 строк и4ответа). Единичный Призрак исправлен на Ангела смерти по двум исходным Angel-развилкам, парной FR-реплике и французскому названию дела; это адресное исключение, не глобальная замена призраков. Уточнены движение такси, другое занятие вместо нового, готовность поверить и колеблющаяся благодарность. Все22544прежних истории/условия сохранены; в C# обновлены только2буквальных ожидания, оба EXE пересобраны. Подробности — LEONIE_FOLLOWUP_CHANGES_RU.md. Текущий статус включения в сборку описан в LEONIE_INTEGRATION_RU.md; историческая редакторская приёмка сохранена.'] if (ROOT/'localization/contexts/051_leonie_followup.json').exists() else []),
        *(['- Ещё раз полностью прочитана четвёртая встреча с Фрагонаром: 39 языковых и смысловых правок. Уточнены последовательность времён, состояние матери, угроза совместной смерти, ощущения полицейского и мелкий хулиган вместо общего мерзавца. Три одинаковых французских свиста сквозь зубы согласованы внутри этой сцены. Имена Эрван/Этан оставлены как неразрешённое противоречие оригинала; все 14 ответов и команды сохранены. Подробности — FRAGONARD04_FOLLOWUP_CHANGES_RU.md. Состояние включения в нативную сборку описано отдельно в FRAGONARD04_INTEGRATION_RU.md; историческая редакторская приёмка сохранена.'] if (ROOT/'localization/contexts/014_fragonard04_followup.json').exists() else []),
        *(['- Дополнительно уточнена подсказка RECLUSE: «Жертва 2 жила затворницей» → «Жертва 2 вела затворническую жизнь». Пол неизвестного человека больше не выдумывается. №2 сохранён по собственному ключу и парному французскому названию вопреки единичному №1 в тексте FR; исключение и отдельная актриса из радио (жертва №3) документированы в RECLUSE_UI_CHANGES_RU.md. Изменено одно поле и его резервное соответствие. Состояние нативного включения описано отдельно в RECLUSE_UI_INTEGRATION_RU.md; исторический момент редакторской правки сохранён.'] if (ROOT/'localization/contexts/000_recluse_batch13_fr_ui.json').exists() else []),
        '- Дополнительно перечитаны обе сцены начальника таксопарка:40 содержательных/языковых ячеек (38 строк и2ответа). Восстановлены мигрень в висках, движение одной руки, утверждение французского оригинала о злости, третье предупреждение и минута одиночества; убраны добавленные намерения и усиления. On согласовано как неопределённые советчики. Точный список с FR/EN и причинами — BOSS_40_CHANGES_RU.md. Эти40правок относятся к новому редакторскому вводу; их включение в нативный пакет проверяется отдельно.',
        '- В нативном парсере исправлен разбор русских реплик с точкой после кавычки: речь больше не теряет подпись говорящего и не становится рассказчиком. Строчные повествовательные обороты отделены от прописных подписей. Все24485строк проверены настоящими.NETмасками, исходные92186инструкций DLL сохранены; подробности и живая проверка — PARSER_FIX_CHANGES_RU.md и LIVE_QA_RU.md. Тексты ресурсов не менялись.',
        '- Пять спорных числовых полей интерфейса приняты по исходным связям документов, дочерних улик и жертв: autopsy04 остаётся жертвой4, фото Ангела01 — местом1, фото Судьи03 — местом3. Русские значения уже были верны, это0новых текстовых/графических правок. Исторический отчёт этого этапа с пятью исключениями и тогда ещё отложенной подсказкой RECLUSE — UI_NUMBERING_CHANGES_RU.md. Иконки и изображения не перерисовывались.',
        '- Крис повторно целиком сверён по французскому: 36 блоков, 169 строк и 18 ответов. Исправлены пауза вместо обрыва речи, направление взгляда, степень уверенности, вопрос о будущем, настоящее время оборванной мысли и несколько буквальных фраз. Недавно построенный дом не стал просто современным по стилю. Встречающий у Каролины человек остаётся без имени; сравнение с бабушкой не сделано родством, обещание водителя не отменяет плату по возможностям. Возраст 19 лет и переход водителя на «ты» сохранены. Все 190 прежних вариантов, проверка обеих случайных историй и два контроля полученного от Каролины согласия оставлены; прохождение не объявлено проверкой всех случайных комбинаций или полной поездки Каролины.',
        '- Йонас повторно целиком прочитан по французскому: 35 блоков, 155 строк, 30 ответов и заказ. Уточнены идиома о неотпускающей религии, согласие вместо простого понимания, самопоправка о механизме, одновременность мыслей и несколько буквальных фраз. Теория о симуляции и компьютерщике-создателе остаётся словами пассажира; прежняя вера принадлежит водителю и не стала нынешней. Два специальных сопоставления французских мыслей с английскими строками сохранены без потерь. Все 6912 прежних вариантов проверки оставлены, добавлено полное сравнение 30 маршрутов. Сбитый dépense в оригинале по-прежнему записан как нерешённый вопрос; прохождение проверки не устанавливает смысл этой фразы.',
        '- Обе встречи Джены заново целиком сверены с французским: 35 блоков, 133 строки и 21 ответ. Отсутствие приоритета у пациентки больше не превращается в отсутствие экстренности; самообвинение врача не стало медицинским или юридическим заключением. Восстановлены «ПЯТЬ секунд», идиома о луне, самопоправка «жалею… нет, не жалею», бодрость вместо внимательности, результат «полегчало» и обрывы фраз. Уже правильные сон и пробуждение сохранены, противоречащие им старые заметки явно отменены. Все 114 прежних вариантов проверки оставлены; добавлено полное сравнение 17 маршрутов. Название жанра «рай» согласовано в трёх исходных употреблениях; у Джанет выполнена только эта точечная орфографическая правка, без новой полной оценки её сцен.',
        '- Франсин, хозяйка Круки, заново сверена целиком по французскому: 32 блока, 127 строк и 17 ответов. Исправлены кивок, неверное «не может» вместо «не хочет понять», буквальное «займёт мой ум», дрожь голоса и несколько неловких фраз. Удушающая забота и лишение свободы переданы как метафора отношений, без ложного признания в физическом удушении кота. Смерть матери отделена от страха за пропавшего Круки; поездка подтверждена только до Сен-Лазара. Сохранены все 234 прежних варианта и четыре проверки связи с реальными исходами сцены кота; добавлено полное сравнение 32 маршрутов. Ответ «Жить дальше?» согласован с выбранной репликой водителя.',
        '- Синдзи повторно целиком сверён по французскому: 35 блоков, 178 строк и 28 ответов. Все 65 строк с японским текстом сохранены посимвольно: водитель не знает их содержания. Уточнены вероятная догадка о туристе, бесстрастный голос и блеск глаз без добавленного утверждения о слезах; исправлено неестественное «под отоплением». Сын из японского рассказа не превратился в жену из догадки водителя. Все 6912 прежних вариантов проверки сохранены, добавлены полные сравнения 23 маршрутов с исходным графом; чаевые и финальная шутка о якудза остаются в своих условиях.',
        '- Шон заново полностью пересверен по французскому: 31 блок, 140 строк, 21 ответ и заказ. Исправлены ранний кивок вместо отрицательного жеста, падежи в разговоре о спортивном костюме, банковская карта вместо недоказанного кредитного типа, прежний рассказ о Франции и несколько буквальных фраз. Пояснение racaille дано рассказчиком, случайное «ты» и последующее «вы» сохранены. Финальный кивок уже был верен; отменена противоречащая ему старая заметка. Сохранены все 756 прежних совместных вариантов проверки, добавлено полное сравнение 16 маршрутов с оригинальным графом. Расхождение фамилии Кристи/Джексон между сценами не замаскировано выдуманным объяснением.',
        '- Повторно сверена сцена Сильви и Сильвена: 12 блоков, 107 строк, семь ответов и заказ. Исправлена буквальная «чашка чая» вместо отношения отца к опере, возвращены слова матери «я на твоей стороне» и наслаждение текущим моментом вместо желания запомнить вечер. Облегчение сына отделено от счастья, приписанного ему матерью; начальное родство остаётся вероятной догадкой до подтверждения в диалоге. Все 12 прежних проверочных маршрутов сохранены и сверены с архивом; добавлено полное сравнение текста, меню, состояний и порядка команд. Отцу не приписана показанная реакция: его в такси нет.',
        '- Фил повторно прочитан целиком по французскому: 30 блоков, 125 строк, 18 ответов и заказ. Исправлены хлопок в ладоши вместо потирания рук, оценивание женщин вместо их записи, несколько буквальных и неловких фраз. В его выдуманной истории уточнён один общий родитель с сестрой, без добавления реальных родственников; сохранена игра наполовину/всем сердцем. Прояснена последовательность сообщений после трёх, четырёх и пяти звёзд. Все 720 прежних маршрутов проверки сохранены, что отдельно сверено с неизменяемой резервной копией; добавлены 144 полных маршрута с проверкой текста, состояний и порядка команд. Общая проверка после этого доходит до следующей сцены; выпуск ещё не готов.',
        '- Полностью пересверена последняя сцена ролевой игры с Пьером-Анри и Шаин: 208 блоков, 814 строк, 104 ответа и заказ. Исправлены руки вместо колец змеиного тела, поступление в колледж вместо подготовительных классов, направление бегства во дворец, числа бросков и восстановление здоровья. Согласованы песня, каламбур «Ксенопопс?», кинжал «Зуб кобры» и отдельное кольцо. Реальные пассажиры отделены от игровых героев; обращения вы/ты сверены по каждой реплике. Исходные ошибки в уроне, флагах смерти и опечатке условия записаны отдельно. Проверены все блоки и ответы, а также полные поездки с исходной случайностью; это не доказательство исправления оригинальной игровой логики.',
        '- Карло пересверен по французскому: восстановлены пчеловод и намеренно ошибочный «пчеловодитель» вместо английских энтомолога и дентомолога. Это слово правильно меняется в пересказе в зависимости от ответа. «Старая груша» оказалась выдержанным грушевым алкоголем; Панзи — бомбардир, сравнение с ударом головой. Сохранена пьяная шутка: показывает три пальца, но говорит «дважды». Все прежние проверки и 315 полных маршрутов сохранены.',
        '- Во встрече со скейтерами восстановлены Эври вместо английского Бордо, анис вместо лакрицы, французское «ПУФ!» и владельцы жестов. Неизвестное пятно не названо определённой жидкостью, живой Блю не объявлен мёртвым; намеренное английское NEVER внутри французского диалога сохранено. У Александра французские 2,30 м, укол сзади в шею и пистолет у виска заменили прежние английские варианты; денежное выражение и различия команд двери отмечены как спорные.',
        f'- В отдельных проходах по интерфейсу вручную сверены {len(batch_keys)} полей; в {batch_changed} текущий русский текст изменён. Исправлены «Эйд» вместо Аде, утрата степени уверенности в газетах, выдуманная биография полицейской, пропущенный лейтенант Бюссе, «LUST» вместо «ЗАВИСТЬ», мотивы убийств, подписи о квартирных ворах, документы вместо автоматически объявленных улик, сроки и число задержаний. Точные ключи, французский оригинал и обе русские версии приведены ниже; спорные исходные номера не приняты автоматически.',
        '- Аннабель полностью пересверена по французскому: 87 блоков, 296 строк, 54 ответа и заказ. «Ты не виновата, что я занялась фотографией» больше не отрицает участие матери в её увлечении. Различены обращения к одному родителю и обоим, восстановлены четыре недели, личный выбор задания и несколько других сроков. Рэпер не ведущий эфира, бледные пассажиры не хмурые, несколько коллег не обязательно двое, малолюдный аэропорт не пустой. Все 1156 прежних полных проверочных маршрутов и отдельные проверки недостижимых концовок сохранены. Перемещение исходного звука двери между выходом и йогой записано как технический долг перед выпуском.',
        '- Клаудия полностью пересверена по французскому: 70 блоков, 289 текстовых слотов, 42 ответа, заказ и три поля интерфейса. Исправлены два перепутанных движения головы, лицо вместо всего тела, шипящий голос и единственная оплата перед поспешным выходом. Деталь произношения возвращена в нужную ветку; два различия числа строк согласованы без потери французского текста и без слияния рассказчика с репликой пассажирки. Улика теперь прямо сообщает, что родителей убила аргентинская хунта; менее конкретная речь Клаудии остаётся отдельным источником. Все 115 прежних проверок сохранены, добавлены 70 полных маршрутов с проверкой строк, состояний и порядка команд.',
        '- Мирей целиком пересверена по французскому: 87 блоков, 265 строк, 67 ответов, заказ и два связанных поля улики. Явно пересмотрено прежнее английское решение о блокноте: французский в двух связанных местах говорит о документе и документах. Правило изменено только для этой сцены; чужие блокноты защищены отдельными проверками. Восстановлены глаза величиной с пятифранковые монеты, ладонь на руке водителя, его прямо названная ложь об источнике сведений, предусмотрительность и конкретные жесты. Муж и Люк остаются двумя людьми, воспоминания о пожаре — свидетельствами. Все 207 проверочных маршрутов сохранены; два исходных расхождения переходов при отказе от кладбища записаны как незавершённая техническая работа до выпуска.',
        '- Полностью пересверена по французскому Леони: 67 блоков, 251 строка, 35 ответов и заказ. Безучастность не стала робостью, ровный тон — холодной отрывистой речью, состоявшийся зевок — подавленным. Восстановлены HEC вместо выдуманного MBA, близкие вместо только друзей, конкретные инструменты, разные водители и слова о доверии. Перемены отношения к музыке и субъективная оценка родителей сохранены. Необычное прозвище «Призрак» в одном французском блоке записано для отдельного решения; имя убийцы по всей игре не менялось. Сохранён полный исходный перебор ответов в четырёх профилях, а недостижимые пороги зевоты проверяются отдельно.',
        '- Полностью сверена по французскому Лола: 40 блоков, 223 строки, 27 ответов и заказ. Сравнение с лимузином и маленьким VIP восстановлено вместо автобуса. Исправлены «я скучаю», дорога на работу, принадлежность родных, рассказы о конфликтах и голосовании. Шутки, грубость, нежность к будущей дочери и скрытый от Ахмеда выбор остаются в своих ветках. Старые решения с приоритетом английского явно пересмотрены; 21 полный маршрут и 12 совместных вариантов сохраняют исходный охват.',
        '- Ада заново целиком перечитана по французскому: 48 блоков, 122 строки, 25 ответов и заказ. Уточнены лаборатория, около сорока датчиков, вероисповедания команды, ABS чужой машины, зевок и повтор инициалов. Исправлены поза, паузы, шутка о захватывающем дух кино и звонок велосипеда. Ада остаётся роботом женского пола; её выводы и намерения не стали доказанными событиями. Все 3456 конечных историй, отдельные финальные профили и передача встречи с Кьярой сохраняются в проверщике.',
        '- Заново полностью пересверена Кьяра: 28 блоков,149строк и14ответов. Усталость не стала уже случившимся сном, а люди со свиданий — неодушевлёнными «свиданиями». Сохранены разные начальники, два сна и два отрезка поездки. Будущий ларёк с такояки назван по французскому без неподтверждённых колёс из английского; прежнее терминологическое решение явно обновлено и защищено отдельным правилом. Слова рассказчика «ей нет25» не подогнаны под карточку26. Все80исходных полных проверочных профилей сохранены; отдельно проверяется передача фактической встречи в воспоминание Ады, без утверждения о новой полной вычитке её сцены.',
        '- Заново полностью пересверены по французскому обе связанные поездки Жеральдины и Аниты: 78 блоков и 248 строк. Согласовано общее вступление; сохранено, какая женщина садится в каждом варианте. Исправлены вопрос о совершённой мести, переданный контакт специалиста, стыд, оставшиеся акции, ресторанный комплимент и переносные выражения. Взгляд Аниты не превратился в прикосновение, ремень безопасности — в оружие, а страх водителя — в доказанное признание. Общие исходные проверки сохранили432профиля Жеральдины с двумя отдельными входами и24разговорных+432закрытых профиля Аниты; владельцы сведений, улики, условия чаевых и разные финалы не упрощены.',
        '- Полностью пересверена по французскому сцена Беренис: 26 блоков, 208 строк, 19 ответов и заказ. Исправлено, кто съёживается, миллиарды вместо миллионов, задержка дыхания и отказ от любых баров. Слова героини о собственной вине сохранены как её переживания. Проверены все 433 обычные истории и 59 отдельных исходных пороговых вариантов; недостижимая из начала речь не получила нового перехода.',
        '- Полностью пересверен французский финал Фрагонара: 65 блоков, 198 строк, 56 ответов и досье. Исправлены два кивка, доверительный тон, документы, обращения и детали действий. После перехода на «ты» сохранены два исходных возврата к «вы». Все три исхода проверены 166 полными маршрутами, покрывающими каждый блок и ответ. Расхождение дат поступления в полицию 1977/после 1979 записано отдельно, даты не подогнаны.',
        '- Проверены 156 коротких полей интерфейса; в 41 исправлен текст. «Конечная смена» стала кнопкой «Завершить смену», новая улика больше не названа подсказкой, одинаковые действия изучения согласованы. Описания дел и сложности следуют французскому; пустая исходная подпись выбора снова пуста. Числовые подстановки сохранены. Проверка расположения текста в игре ещё предстоит.',
        '- Журнал интерфейса теперь строится по актуальной таблице, включая новые изменения, отсутствовавшие в старом списке. Сравнение «Было» относится к исходной таблице по ключам; если ключа там не было, это отмечено отдельно. Старый мод мог показывать текст через дополнительный поиск, поэтому отсутствие ключа не объявляется пустой надписью в игре. История прежних решений сохранена, актуальные изменения также находятся в review/current_ui_changes.json.',
        '- По французскому оригиналу целиком отредактированы все пять мест расследования Судьи: 158 блоков, 309 строк, 76 ответов и 34 поля интерфейса. Восстановлены обращения Элен, характер консьержа, женщина — хозяйка оружейного магазина, служебный дом Марко и футбольная видеоигра. Исправлено, кто именно молчал при встрече с Салимом; слухи о тренере и обвинения свидетелей не стали доказанными фактами. «Процесс» согласован как название аргентинского военного режима. Пять пустых служебных подписей возвращены к исходной пустоте. В обоих оригиналах воспроизведена и точечно исправлена опечатка ссылки, обрывавшая ветку нехватки денег в посольстве. Отдельное исходное противоречие — требование 250 евро при обещанной цене 200 — записано и сохранено. Исходные файлы не переписаны; производные для проверки явно отмечены.',
        '- По французскому оригиналу целиком отредактированы больница, встреча с Марко и архив эскорт-агентства: 149 блоков, 301 строка, 68 ответов и 14 полей улик. Восстановлены пол говорящих, ложные отговорки водителя, намёки вместо «симптомов», выпитый залпом бокал и фамилия Бретон вместо «бретонца». Намеренно исковерканные выражения Марко сохранены. Водонагреватель, предохранитель, визитка, квитанция и список клиентов получили устойчивые названия. Один английский ответ вёл на несуществующий блок: переход восстановлен строго по французскому оригиналу и защищён отдельной проверкой. Больница и кафе проверяются полными парными историями, архив — по достижимым состояниям меню и всем их ответам; повторные одинаковые истории архива не выдаются за проверенные целиком. Выдача улик, условие правды, порог оплаты 15 евро и разные исходы поиска документов сохранены.',
        '- По французскому оригиналу целиком отредактированы встреча со смотрителем Батиньоля и разговор с телеведущим в редакции: 79 блоков, 177 строк, 40 ответов и 12 полей улик. Восстановлен говорящий в реплике о верности Александру, метрические величины, переход на «ты», жесты и смысл бытовых предметов. Даниэль согласован как мужчина; исправлены идиомы о деньгах, недоказанные подробности и финальный хлопок глушителя. Расспросы по-прежнему позволяют выбрать ровно двух жертв. Проверены 4416 полных пар французских/русских маршрутов в самостоятельном штатном движке. Это первые две сцены отдельной французской сверки; предыдущие редакции требуют её прохождения.',
        '- Целиком сверены церковь, встреча с Этьеном и «Бельведер» по делу Ангела смерти: 98 блоков, 215 строк, 54 ответа и 18 полей девяти улик. Гильда стала подозреваемой вместо «подопечной», восстановлены имя Йонаса Пьерссона и символ ихтис; бар и барменша согласованы с остальными сценами. Свидания Жюля больше не приписывают его спутникам определённый пол; ирония Этьена о прибранной квартире и сарказм отказа барменши восстановлены. Улики и обвинения остаются словами персонажей. Проверены 24720 полных пар английских/русских маршрутов из начала сцен; варианты цен 50/250 евро получили ещё 168 отдельных контрольных прогонов. Исходные расхождения счётчиков цены и флагов знакомства не исправлялись переводом; проверка вне Unity не подтверждает всю игровую оркестрацию.',
        '- Целиком сверены кладбище Пасси и пожарная часть по делу Ангела смерти: 60 блоков, 122 строки, 30 ответов и 14 полей семи улик. Исправлены «первозданный» вместо безупречного человека, ложная определённость вопроса о самоубийстве, фырканье вместо шмыганья носом, взгляд через чужое плечо и ответ о полезности сведений. Закреплены Поль, Симон Коллон, Танги и Зита Вельпо; Танги — покойный любимый мужчина Поля, не родственник водителя. Название культа согласовано с досье и французским оригиналом. Исходные различия «никого / не всех» и обычно недостижимая реплика Марко сохранены с пояснениями. Штатный движок прошёл 4448 полных пар английских/русских маршрутов при разных предыдущих посещениях; три дополнительных входа проверяют недостижимую реплику отдельно. Это проверка диалогов вне Unity, не готовая установленная сборка.',
        '- Полностью сверены 101 уличное наблюдение и два варианта провала: 111 блоков, 144 строки и три ответа. Восстановлены смысл срабатывания камеры скорости, профессия уборщиков, киноактёр мужского рода, бар «Бельведер», движение вдоль кладбища и выход зрителей после спектаклей. Сохранены подпись «БОСС», рабочая лицензия, отдельные исходы трёх дел и фабрикация обвинения вместо признания в убийствах. Пустой удалённый блок 76 оставлен пустым; исходные ограничения показа и опечатка в случайном переходе не переписаны переводом.',
        '- Полностью сверены доска расследования и три звонка Бюссе: 72 блока, 168 строк, 26 ответов и 24 названия/источника документов. Исправлены просьба сказать время, участок вместо станции, обращения на «вы», непереведённые подписи и буквальные идиомы. Исчезли фотографии племянников, а не дети; подозрение во вторжении остаётся сомнением. Женский род Бюссе закреплён по репликам, все варианты алиби, отложенного ответа и повторного выбора подозреваемого сохранены.',
        '- Полностью сверены восемь сценариев заправки: 77 блоков, 107 строк и 30 подписей/источников улик. Исправлены непереведённый продавец, насосы вместо бензоколонок, буквальные идиомы, взятки вместо развращённости и субъект безобидной внешности. Сохранены неопределённость свидетельств, ожидание поимки вместо сообщения о ней, условные чаевые, исходные выигрыши и все игровые команды. Шесть внешних входов лотереи подтверждены по коду игры; проверка структуры не заменяет прохождение в игре.',
        '- Полностью сверены три встречи с Ксавье: 86 блоков, 367 строк, 73 ответа и три фразы заказа. Восстановлены пропущенные реплики, ответы, оговорка про Бэтмена и начало третьей встречи вместо чужой пассажирки. Мужской род подтверждён текстом вопреки нулевым полям карточки; точный возраст не придуман. Сохранены разные исходы поездки с бомбой, строгий порог времени, авария, радио и поведение при панике.',
        '- Полностью сверена Роксана: 28 блоков, 83 строки, 19 ответов и заказ. Восстановлены пропуски и избранность водителя в её рассказе. Сохранены разные ветки знакомства с Людвигом, её противоречивые советы и ненадёжность утверждений о призраках. Исправлены бег вместо страха, текущего по венам, обращение «сэр» и лишний значок ответа; исходная бесплатная поездка сохранена.',
        '- Полностью сверён Альф: 34 блока, 152 строки, 27 ответов и заказ. Сохранены двойные приветствия и странные синонимы, намёки без выдуманной личности, неполное имя водителя, разница франков и евро и условный гипноз. Потеря голоса и паралич происходят во всех ветках, как в оригинале.',
        '- Полностью сверена Натали: 61 блок, 205 строк и 33 ответа. Восстановлены реплики, выбор о детях, разговор о возрасте и профессиях, внуки вместо подростков. Водитель здесь пассажир; ложные имена и профессии не меняют его биографию. Имя сына Редуан закреплено по прямому тексту. Сохранены оговорки Натали и расхождение возраста 72 в речи и 74 в карточке.',
        '- Полностью сверён Джим: 47 блоков, 137 строк, 47 ответов и заказ. Восстановлены пропуски, шутка о недвижимости и точные заказы кофе и пива. Исправлены обращения, кулинарные выражения и память о Камий. Написанные в оригинале, но недостижимые из обычного начала финалы сохранены без изменения сюжета.',
        '- Полностью сверены обе встречи с Мельхиором: 128 блоков, 368 строк, 115 ответов и два заказа. Восстановлены пропуски и воспоминания об Аде, исправлены идиомы, расширенный зрачок вместо перегоревшего, вопросы вместо просьб ударить. Согласованы нейрошлюз, два голоса, имена, род и владельцы семейных историй. Сохранены оговорки, различия оригиналов, случайные выборы и исходно недостижимые фрагменты; сюжетные переходы не переписаны.',
        '- Полностью сверена Беренис: 26 блоков, 208 строк, 19 ответов и заказ. Восстановлены пропуски, реальные действия вместо выдуманных реплик и свиста, двойное «не знаю» и адресат полуулыбки. Различены рассказ героини, самообвинения, слова друзей и ответы водителя; сохранены неоднозначные воспоминания и расхождение возраста в исходниках. Исправлены буквальные идиомы, топонимы и неприятные смысловые подмены.',
        '- Полностью сверены Надя и Ив: 39 блоков, 150 строк, 40 ответов и заказ. Пара не стала матерью и сыном; возраст каждого отделён от общей карточки. Исправлены обращения, пропуски, достаток вместо самочувствия, сны вместо мечтаний и направление поддержки в финале. Купюра за дополнительную просьбу отделена от платы за поездку, сохранены все исходные суммы, условия и концовки.',
        '- Полностью сверены шесть сцен Миртиль: 89 блоков, 370 строк, 42 ответа и четыре фразы заказа. Восстановлены начало первой загадки, пропущенные строки и верные говорящие; исправлены буквальные идиомы. Согласованы Миртиль, её подруга Симона, хозяйственная сумка и формулировки загадок. Уговор об оплате, намеренно неверные ответы и память о победах сохранены; расхождения английского и французского оригиналов объяснены отдельно.',
        '- Полностью сверена Лола: 40 блоков, 223 строки, 27 ответов и фраза заказа. Убрано чужое начало Шанталь, восстановлены смещённые блоки и смысл идиом. Сохранены беременность дочкой, отношения с Ахмедом, владельцы семейных воспоминаний и условный рассказ о голосовании; её слова и газетные слухи не превращены в подтверждённые факты.',
        '- Досье Пьеро Батаза восстановлено по ключу `059_pierrot.bio`: полицейский, рост 1,70 м. Досье почтальона принадлежит Александру Леклеру.',
        '- Все 14 досье сверены с английскими ключами. Исправлены чужие биографии, неверный рост, пропуски, пол и профессии.',
        '- Полностью отредактирована поездка с Круки: 40 блоков, реплики, действия и ответы. Исправлены буквальные идиомы, неверный порядок, пропущенные действия, выдуманные реплики и смысл хозяйки, которая слишком ласкова.',
        '- Полностью сверены восемь сцен образа с лицом водителя: 91 блок, 412 строк, 47 ответов и шесть ключей улик. Служебное имя не раскрыто вместо «???». Чужое начало про мигрень убрано из воспоминания об Ангеле смерти; выдуманное самоубийство заменено исходной репликой «У меня не было выбора». Исправлены женские обращения к водителю, Панама вместо Парижа, колледж вместо университета, «гнутый кахба» вместо намеренной арабской ругани, потерянные жесты и слова. Жюли и медсестра Синтия различены; правда о страхе и ложь о непривлекательности не объединены. Поздние сведения об отце и брате записаны с источниками без спойлеров в ранних репликах. Рост, извинение и морщины разделены по делам, вопрос об источнике сна сохранён. Все 150 вариантов повторного появления проверены отдельными контролируемыми входами; обычные случайные поездки и переход памяти перед сном проверяются отдельно штатным движком.',
        '- Полностью сверена поездка с Сантой: 32 блока, 178 строк, 19 ответов и заказ. Восстановлены пропущенные слова и действия, убраны ответы, ошибочно вставленные в повествование. «Очистить палитру» стало «рот прополоскать», GSM — мобильниками, а одна полудюжина оленей — исходными двумя. Сани согласованы как один предмет; правило не принимает метку говорящего «САНТА» вместо самого слова. Сохранены болезненные намёки на брата и тюрьму, два случайных финала и отдельное ожидание без увиденных саней. Необъяснённое знание пассажира и сомнение водителя не получили придуманного объяснения. Проверен переход к вопросу о Санта-Клаусе перед сном.',
        '- Полностью сверены шесть сцен Анжелики: 81 блок, 441 строка, 61 ответ и четыре заказа. Исправлены смещённое начало о банковском счёте, незаметная съёмка, принадлежность духов, мех вместо шерсти и буквальные ошибки в ругательствах. Муж Жан-Пьер, сын Жан-Ролан и соседский мальчик различены; расставание не объявлено состоявшимся разводом. Самоописание речевых приступов, намеренный оттенок одного выкрика и поздние сомнения сохранены без добавленного диагноза. Подсказка «титьки»/«т» согласована, исходные расхождения EN/FR записаны. Проверены все ответы, девять случайных повторных посадок и переход знания о «Ла Пьер» к Пьеретт.',
        '- Анри заново целиком пересверен по французскому: 39 блоков, 137 строк, 29 ответов и заказ. Муйетт — собака женского пола; намеренная ошибка водителя сохранена. Старые решения с приоритетом английского явно отменены: угрозы не были пустыми словами, водитель говорит о привязанности к собаке. Исправлены чувствительность вместо стиля, собака на коленях, рычание и предположительная причина боли. Нафталин узнаётся только в конце, реинкарнация остаётся верой пассажира. Обновлены устаревшие эталоны; недостижимые большие чаевые проверяются отдельными входами. Реально завершённые ветки Эмилии передают флаг знакомства в воспоминание Анри. Мужчина Анри и женщина Дженабу Анри остаются разными людьми.',
        '- Эмилия заново целиком пересверена по французскому: 48 блоков, 235 строк, 42 ответа и заказ. Помимо прежних исправлений университета, пола кота и пропусков, восстановлены извинение вместо спасибо, семестр вместо учебного года, неопределённая ошибка дозировки и повтор «повсюду». Её постепенные признания, разные действия с котом, условные сведения об ассистенте и память о брате сохранены. Движение и вспышка памяти соответствуют оригиналу, новые подробности не добавлены. Все исходные меню, состояния, команды и их порядок проверяются 70 полными маршрутами; это не все сочетания предшествующих ответов и не проверка в Unity.',
        '- Полностью сверена Мириам: общая посадка и три альтернативных рассказа по делу — 92 блока, 363 строки, 59 ответов и заказ. Восстановлены начало истории о синяках ребёнка, пропущенные реплики, паузы и действия; чужие строки удалены. «Приходил к вам» исправлено на «ухаживал», уточнён отец подопечного, а не собственный отец Мириам. Девятнадцать лет и неопределённый уровень учёбы закреплены; отрицание детей водителем сохранено как явная ложь. Разные семьи, случайное решение ехать в полицию, скрытый счётчик интереса и память о старшем брате не объединены в новый сюжет.',
        '- Полностью сверена поездка Софи и Марка: 28 блоков, 119 строк, 8 ответов и заказ. Восстановлены пропущенные реплики о коллекции, настроении Марка, уходе Софи в отель, её оплата и общий финал. Команда без руководителя больше не названа расформированной. Сохранены скрытая боль за вежливостью, разные финальные пассажиры при выборе отопления и условные упоминания детей.',
        '- Полностью сверена Пьеретт: 44 блока, 150 строк, 27 ответов, заказ и три ключа досье/улик. Исправлены выдуманная вспышка гнева вместо опущенных глаз, чужие слова о пении, «гивашиты», приказ таксисту готовить и «Пропащая» вместо паузы. Закреплены шеф-женщина, переход на «ты», правдивый район детства водителя Ла Тимон и Обань как ложь. Ужин, вино, осмотр квартиры и улика про шрам остаются условными; досье не переписано по словам пассажирки о деньгах.',
        '- Полностью сверена Аннабель: 87 блоков, 296 видимых строк, 54 ответа и фраза заказа. Исправлены связь в туннеле, возможность заняться йогой, адресат-мать, ускорение речи вместо шага, оплата поездки и подмена благодарности за звонок репликой о радио. Неизвестные имена и маршрут между Ливией/Грецией не выдуманы; исходные недостижимые здесь условия отдельно описаны.',
        '- Полностью сверена Аньес: 38 блоков, 139 строк, 17 ответов и заказ. Сохранены женщина с бородой, самостоятельность, бывший муж и дети без выдуманных причин или диагноза. Исправлены поздний прилёт, облегчение, дорожная косметичка, двадцать лет бритья и пропущенное намерение выгнать бывшего мужа; узнавание Франсуа связано с реальной встречей.',
        '- В предыдущем проходе по Мирей сверены 87 блоков, 265 строк, 67 ответов, заказ и два UI-ключа. Убрано выдуманное время поезда и ориентация актёра, восстановлены стихи, муж и Люк, прощание и запах цветов апельсина. Прежнее английское решение о блокноте позднее явно отменено французской сверкой в пользу документов; актуальное решение описано выше. Одна дорожная сумка, разные сроки и показания о пожаре сохранены.',
        '- Полностью сверён Дени: 35 блоков, 126 строк, 29 ответов и заказ. Сельская жизнь больше не названа жизнью в стране; интернет-оскорбления не превратились в признания пассажира. Восстановлены сведения о жене, коровах, монтаже, требовании публичных извинений и газете. Намеренные Твити/Интырнет/поиск слова мемы сохранены; противоречие EN/FR и управляющего флага описано.',
        '- Полностью сверена Полин: 49 блоков, 191 строка, 29 ответов и заказ. Восстановлены отгулы, взаимность, паспорт без придуманной причины, жесты и все три обещания сведений по делам. Любимая из Сиэтла — женщина, контакт — неназванный мужчина; обещание не объявлено полученной уликой. Первоначальный заказ Ла-Мотт-Пике, разворот в аэропорт и исходная логика выбора сохранены.',
        '- Целиком сверены семь встреч с Джанет: 83 блока, 391 строка, 51 ответ, а также 31 газетная улика/62 ключа. Исправлены подменённое начало, возраст20 вместо20летназад, записать вместо запомнить, папка/инициалJ, жесты и испорченные обрывки. Имена и временные противоречия источников закреплены явно. «Отличная журналистка» больше не фантаст; арест относится к виновнику убийства алжирца, а безобидный вид — к убийце. Аргентинский «Процесс» не судебный процесс. Противоположные сведения газет/архивов сохранены как разные свидетельства.',
        '- Целиком сверена Нина: 36 блоков, 135 строк, 27 ответов и заказ. Восстановлены отказ на предложение, поспешность, связь как песня, рассказ о Брисе, звонкая злость/хрупкость/внутренняя речь, просьба о тайне и последняя реплика. Подозрение в измене не стало фактом; роза, кольцо и туфли получили верные действия. Rage>3 при обычном максимуме3 и обе случайные судьбы розы сохранены. Rue de Lévis согласовано как улица де Леви: [французское произношение Lévis](https://fr.forvo.com/word/l%C3%A9vis/).',
        '- Устранён пропуск ответов в блоках без реплик: в исходном моде обработка ответов находилась внутри замены строк. Встроенный патч обрабатывает их независимо.',
        '- Восстановлены 23 полностью пустых текстовых блока у других пассажиров.',
        '- Исправлены пропущенные варианты ответа, в том числе несколько самостоятельных ответов, ведущих в один блок.',
        '- Восстановлен точный идентификатор ветки аварии Матьё: `mathieu-01-hospital-car accident`.',
        '- Добавлены 146 отсутствующих ключей интерфейса. Названия источников улик теперь привязаны к точным ключам. Технический ключ `KEY=ENG` сохранён.',
        '- Исправлены «Тарифы» в отчёте о выручке, «Общие сведения» в меню настроек, род подписи скорости и другие формулировки интерфейса.',
        '- Убрана служебная строка `tell=1`, ошибочно попавшая в видимый текст Франсин.', '',
        '## Проверочная сборка r1: способ установки', '',
        '- Собран вариант без BepInEx, Harmony и перехвата TMP-текста. Перевод находится непосредственно в ресурсах игры.',
        '- Изменяются `Night Call_Data/resources.assets`, `Night Call_Data/sharedassets0.assets` и `Night Call_Data/Managed/Assembly-CSharp.dll`.',
        '- В английский слот локализации записан русский текст, название языка в меню — «Русский».',
        '- Кириллические подписи говорящих поддерживаются небольшой правкой штатного регулярного выражения. Для Синдзи сохранён выбор японского шрифта после перевода подписи говорящего.',
        '- В 10 SDF-шрифтов добавлены А–Я, а–я, Ё и ё, а также недостающие кавычки, тире, многоточие, знак евро и знак номера. Исходные символы и их пиксели сохранены.',
        '- Оригинальные переходы, переменные, окончания ответов, эмоции и последовательности служебных команд сохранены и проверены после записи ресурсов.',
        '- Установщик проверяет SHA256, сохраняет исходные файлы, проверяет результат копирования и откатывается при ошибке. Повторная установка идемпотентна. Для другой версии игры установка блокируется.', '',
        '## Проверка и границы', '',
        f'- Последний зафиксированный общий прогон диалогового движка: {"PASS" if story_report["passed"] else "FAIL"}, {story_report["checks"]} успешных проверок. Ввод `{story_report["input_sha256"]}`. Он подтверждает только проверенные ветки этого ввода; новая редактура требует нового экспорта и проверки.',
        '- Готовность релиза требует успешной общей проверки, новой нативной сборки, проверки игровых экранов, сохранений, установки и отката. Французская редактура текста сама по себе этого не доказывает.', '',
        'Исторические результаты проверочной сборки r1 (последующая французская редактура ещё требует новой сборки):', '',
        f'- В r1 проверены {valid["counts"]["dialog_objects"]} объектов, {valid["counts"]["passages"]} блоков, {valid["counts"]["choices"]} ответов и {valid["counts"]["ui_entries"]} ключей интерфейса.',
        f'- {valid["counts"]["unchanged_objects_byte_verified"]} незатронутых объектов в двух ресурсах побайтово совпали с оригиналом.',
        '- В отдельной копии запущена Night Call 1.3.7: русское главное меню, настройки и название языка визуально проверены.',
        '- Десять проверок настоящего Prompter.dll прошли для веток Круки, Матьё и Кристофа. Это проверка движка диалогов вне игрового процесса, а не прохождение пассажиров в игре.',
        '- В раннем сканировании r1 отмечены `ENG` (техническая строка таблицы) и `ENKID` (сюжетная аббревиатура). Это не полный список намеренных латинских собственных имён и фраз нынешней редакции.',
        f'- Текущая проверка корпуса сообщает {stats["findings"].get("visible_line_count",0)} расхождений числа видимых строк с техническим носителем. Это структурная проверка, а не самостоятельное доказательство точности перевода или отображения в игре.',
        '- Исходный машинный перевод использовался как черновик. Текущий охват ручной французской сверки указан выше; совпадение с черновиком само по себе не считается ошибкой.',
        '- Полное прохождение, все игровые экраны и все ветки пассажиров не проверены. Текущая сборка предназначена для проверки и дальнейшей редактуры.',
        '## Подписи говорящих', '', '| До | После | Вхождений в ресурсах |','|---|---|---|']
    for (before,after),count in sorted(speakers.items()): lines.append(f'| {before} | {after} | {count} |')
    if legacy_changes:
        lines += ['', '## Унаследованные подписи старого мода', '',
                  'Эти записи сохраняют совместимость старых поисковых подписей с уже проверенными именами и текстом. Это не новые ключи оригинальной игры и не подтверждение перевода всех надписей, встроенных в код. «Было» взято из исходной таблицы старого перевода.', '',
                  '| Подпись или служебный идентификатор | Было | Стало |', '|---|---|---|']
        esc=lambda s:html.escape(str(s or '')).replace('|','\\|').replace('\n','<br>')
        for x in legacy_changes:lines.append('| '+esc(x['alias'])+' | '+esc(x['baseline'])+' | '+esc(x['russian'])+' |')
    lines += ['', '## Все записи редактуры', '',
              'Повторяющееся обоснование приводится один раз для каждой группы. В остальных записях дана ссылка на него; английский оригинал, старый и новый русский текст, а также варианты ответа сохранены для каждой правки.', '']
    reason_anchors={}
    for number,x in enumerate(changes,1):
        ref=x.get('key') or x['object']+' / '+x['passage']
